async def act(page):
    """
    From the current "New Rule / Magento Admin" page state, ensure the shopping cart price rule
    applies to ALL customer groups, set the Action to a fixed $15 discount, and save the rule.

    Constraints observed from the UI state:
    - The General Information fields are already filled (Rule Name, Description, Status, Websites).
    - Customer Groups listbox exists inside the table and must be set so the rule applies to all customers.
    - The Actions tab must be opened to access the Apply combobox and Discount Amount field.
    - Clicking Save will navigate away; make that the final action.

    No knowledge-base helper functions are available in the environment, so all interactions use
    Playwright accessibility-role selectors (page.get_by_role and relative chains) and select_option/fill/click.
    """
    # Wait for DOM to be ready
    await page.wait_for_load_state("domcontentloaded")

    # 1) Ensure Customer Groups selects every group so the rule applies to all customers.
    try:
        # Access the listbox via the containing table per the accessibility tree to avoid ambiguity
        table = page.get_by_role("table")
        if await table.count() > 0:
            customer_groups_lb = table.get_by_role("listbox", name="Customer Groups *")
            if await customer_groups_lb.count() > 0:
                await customer_groups_lb.first.select_option([
                    {"label": "NOT LOGGED IN"},
                    {"label": "General"},
                    {"label": "Wholesale"},
                    {"label": "VIP Member"},
                    {"label": "Private Sales Member"},
                ])
            else:
                # Fallback: try any listbox inside the table and attempt to select known labels
                all_listboxes = table.get_by_role("listbox")
                for i in range(await all_listboxes.count()):
                    lb = all_listboxes.nth(i)
                    try:
                        await lb.select_option([
                            {"label": "NOT LOGGED IN"},
                            {"label": "General"},
                            {"label": "Wholesale"},
                            {"label": "VIP Member"},
                            {"label": "Private Sales Member"},
                        ])
                        break
                    except Exception:
                        continue
    except Exception:
        # Tolerate failures and continue; we'll still attempt to set Actions/Discount and save
        pass

    # Small pause to allow any UI updates
    await page.wait_for_timeout(250)

    # 2) Reveal the Actions tab so we can set Apply and Discount Amount (harmless if already active)
    try:
        actions_link = page.get_by_role("link", name="Actions")
        if await actions_link.count() > 0:
            await actions_link.first.click()
            await page.wait_for_timeout(400)
    except Exception:
        # Continue even if we couldn't click the tab; controls may already be visible
        pass

    # Helper: try multiple combobox names and option labels
    async def try_select_combobox_by_labels(names, labels):
        for nm in names:
            try:
                combo = page.get_by_role("combobox", name=nm)
                if await combo.count() > 0:
                    for lbl in labels:
                        try:
                            await combo.first.select_option({"label": lbl})
                            return True
                        except Exception:
                            continue
            except Exception:
                continue
        return False

    # 3) Set Apply / Action to "Fixed amount discount"
    await try_select_combobox_by_labels(
        names=["Apply", "Action", "Apply To", "Apply the rule", "Apply *"],
        labels=["Fixed amount discount", "Fixed Amount Discount", "Fixed"],
    )

    # 4) Fill Discount Amount = 15. Try spinbutton first, then textbox, with fallbacks.
    async def try_fill_numeric(names, value):
        for nm in names:
            try:
                spin = page.get_by_role("spinbutton", name=nm)
                if await spin.count() > 0:
                    await spin.first.fill(value)
                    return True
            except Exception:
                pass
            try:
                txt = page.get_by_role("textbox", name=nm)
                if await txt.count() > 0:
                    await txt.first.fill(value)
                    return True
            except Exception:
                pass
        # Fallback: any spinbutton
        try:
            all_spins = page.get_by_role("spinbutton")
            if await all_spins.count() > 0:
                await all_spins.first.fill(value)
                return True
        except Exception:
            pass
        # Fallback: any textbox
        try:
            all_texts = page.get_by_role("textbox")
            for i in range(await all_texts.count()):
                t = all_texts.nth(i)
                try:
                    await t.fill(value)
                    return True
                except Exception:
                    continue
        except Exception:
            pass
        return False

    await try_fill_numeric(["Discount Amount", "Discount Amount *", "Discount", "Amount"], "15")

    # brief wait for dynamic UI updates
    await page.wait_for_timeout(200)

    # 5) Click Save as the final action (expected to navigate away)
    try:
        save_btn = page.get_by_role("button", name="Save")
        if await save_btn.count() > 0:
            await save_btn.first.click()
            return
    except Exception:
        pass

    # Fallback: Save and Continue Edit
    try:
        save_continue = page.get_by_role("button", name="Save and Continue Edit")
        if await save_continue.count() > 0:
            await save_continue.first.click()
            return
    except Exception:
        pass

    # If no save control found, finish without navigation
    return

